  // Add route handling logic here
  if (req.url === '/success') {
    const successResponse = createSuccessResponse('Operation successful', { data: 'example' });
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(successResponse));
  }
  // Add error route handler here
});

// Define createResponseEnvelope function here
function createResponseEnvelope(success, message, data, errorCode) {
  return {
    success,
    message,
    data: success ? data : undefined,
    errorCode: success ? undefined : errorCode
  };
}

// Create createSuccessResponse function here
function createSuccessResponse(message, data) {
  return createResponseEnvelope(true, message, data);
}

// Create createErrorResponse function here
function createErrorResponse(message, errorCode) {
  return createResponseEnvelope(false, message, null, errorCode);
}

